/* Model creation/destruction functions */

void MODEL_mkTbTop::create_model(tSimStateHdl simHdl, bool master)
{
  sim_hdl = simHdl;
  init_reset_request_counters(sim_hdl);
  mkTbTop_instance = new MOD_mkTbTop(sim_hdl, "top", NULL);
  bk_get_or_define_clock(sim_hdl, "CLK");
  if (master)
  {
    bk_alter_clock(sim_hdl, bk_get_clock_by_name(sim_hdl, "CLK"), CLK_LOW, false, 0llu, 5llu, 5llu);
    bk_use_default_reset(sim_hdl);
  }
  bk_set_clock_event_fn(sim_hdl,
			bk_get_clock_by_name(sim_hdl, "CLK"),
			schedule_posedge_CLK,
			NULL,
			(tEdgeDirection)(POSEDGE));
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_walker_startW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_walker_takeW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_respW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_pulledW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_reqTakenW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_getW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_startFmtW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.INST_r_startDataW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rd.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_mem_wrW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_mem_rdW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_cfgW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_planW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_putW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_rewW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_advW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_rdW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_bb_fixW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rs_startW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_rs_getW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_pl_startW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_pl_byteW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_pl_endW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_pl_takenW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.INST_startW.set_clk_0)("CLK");
  (mkTbTop_instance->INST_dut.set_clk_0)("CLK");
  (mkTbTop_instance->set_clk_0)("CLK");
}
void MODEL_mkTbTop::destroy_model()
{
  delete mkTbTop_instance;
  mkTbTop_instance = NULL;
}
void MODEL_mkTbTop::reset_model(bool asserted)
{
  (mkTbTop_instance->reset_RST_N)(asserted ? (tUInt8)0u : (tUInt8)1u);
}
void * MODEL_mkTbTop::get_instance()
{
  return mkTbTop_instance;
}

/* Fill in version numbers */
void MODEL_mkTbTop::get_version(char const **name, char const **build)
{
  *name = "2021.12.1";
  *build = "fd501401";
}

/* Get the model creation time */
time_t MODEL_mkTbTop::get_creation_time()
{
  
  /* Fri Nov  6 13:09:58 UTC 2026 */
  return 1793970598llu;
}

/* State dumping function */
void MODEL_mkTbTop::dump_state()
{
  (mkTbTop_instance->dump_state)(0u);
}

/* VCD dumping functions */
MOD_mkTbTop & mkTbTop_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbTop *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbTop(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkTbTop::dump_VCD_defs()
{
  (mkTbTop_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbTop::dump_VCD(tVCDDumpType dt)
{
  (mkTbTop_instance->dump_VCD)(dt, vcd_depth(sim_hdl), mkTbTop_backing(sim_hdl));
}
